require_relative 'driver'
case_image('erase-09','h=pencil();h:rule({100,80},{800,80},{pressure=0.8});','erase(rect(300,20,200,130),{strength=0.9});print(drawing_guide():area())')
WET='work(rect(200,20,500,150),{pile=p,hand="detail",coverage=2,clip=true,seed=1});r=rag{width=40,seed=1};print(drying(400,80));'
case_image('rag-pressure-half',WET,'r:wipe({{300,80},{600,80}},{pressure=0.5,seed=1});print(r.load,r.soaked)')
case_image('rag-baseline',WET,'print(r.load,r.soaked,wait(0))')
%w[red-earth raw-umber lead-white bone-black].each{|mat|fresh('stage-'+mat,"p=pile{{\"#{mat.tr('-',' ')}\",1}};work(rect(350,50,100,60),{pile=p,hand=\"detail\",coverage=3,clip=true,seed=1});");run('print(wait(0),drying(400,80));for _,n in ipairs{5,10,15,30,60,120,240,480,960,1440,2880,5760} do print(wait(n),drying(400,80)) end')}
# Correct same-seed single-table constructor controls.
%w[firm searching broken soft].each{|ch|case_image('outline-'+ch,'pts={{200,30},{400,30},{450,140},{250,140}};b=brush("round",4);',"o=outline{pts=pts,char=\"#{ch}\",seed=1};n=#o:strokes();len=o:length();print(o:paint(b,{dip={p,0.6},every=3}),b:fullness());print(n,#o:strokes(),len,o:length())")}
{'amount'=>'amount=0','size'=>'size=20','lobe'=>'lobe=20','edge'=>'edge=10','seed'=>'seed=2'}.each{|k,v|case_image('outline-'+k,'pts={{200,30},{400,30},{450,140},{250,140}};',"o=outline{pts=pts,#{v}};print(o:length(),o:mask():area());work(o:mask(),{pile=p,hand=\"detail\",clip=true,coverage=1,seed=1})")}
fresh('shape-retention','pts={{200,30},{400,30},{450,140},{250,140}};');run('ix={1,3};o=outline{pts=pts,corners=ix,seed=1};print(#o:corners(),o:length());ix[1]=2;pts[1][1]=100;o2=outline{pts=pts,corners=ix,seed=2};print(#o:corners(),o:length(),o2:length());for _,k in ipairs{"firm","searching","broken","soft"} do a=outline{pts=pts,char=k,seed=1};b=outline{pts=pts,char=k,seed=1};print(k,a:length(),b:length(),a:mask():area(),b:mask():area()) end;for _,v in ipairs{0,0.8,1} do local b=body_of{spine={{200,80},{500,80}},widths={40,30},limbs={{pts={{350,80},{350,140}},widths={20,10}}},blend=v,seed=1};print("body",v,b:mask():area()) end;local a=body_of{spine={{200,80},{500,80}},widths={40,30},seed=1};local b=body_of{spine={{200,80},{500,80}},widths={40,30},char="soft",seed=1};print("softdefault",a:mask():area(),b:mask():area());m=rect(300,40,200,100);print("roughen",m:area(),m:roughen(10,40,1):area(),m:area())')
# Dampness and physical defaults; state and clock restore on actual failed chunk.
fresh('rag-rollback',WET);run('r:dip(1);print(r.load,r.soaked,r.damp,r.fold,wait(0))');shot('rag-rollback-before');run('r:wipe({{300,80},{600,80}},{seed=1});r:refold();error("rollback")');run('print(r.load,r.soaked,r.damp,r.fold,wait(0))');shot('rag-rollback-after')
fresh('rag-default');run('a=rag{seed=1};b=rag{width=400,seed=1};a:dip();b:dip(0.5);print(a.width,b.width,a.damp,b.damp);a:refold();print(a.fold,a.damp)')
# no real-time aging: output and image after independent 60second sleep.
fresh('idle',WET);run('r:dip(1);print(wait(0),drying(400,80),r.damp)');shot('idle-before');t=Time.now;sleep 60;cli('status');run('print(wait(0),drying(400,80),r.damp)');shot('idle-after');$results << {idle_wall_seconds:Time.now-t};File.write(File.join(OUT,'marks-results.json'),JSON.pretty_generate($results));cli('close')
